CREATE TABLE gcg_card_row(id TEXT PRIMARY KEY,run_id TEXT NOT NULL,kind TEXT NOT NULL,ordinal INTEGER NOT NULL,native_id TEXT NOT NULL,source_path TEXT NOT NULL,pointer TEXT NOT NULL,raw_json TEXT NOT NULL,UNIQUE(source_path,ordinal)) WITHOUT ROWID;
CREATE TABLE gcg_card_slot(id TEXT PRIMARY KEY,row_id TEXT NOT NULL REFERENCES gcg_card_row(id),field TEXT NOT NULL,locale TEXT NOT NULL,raw_locator TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('resolved','missing','ambiguous')),UNIQUE(row_id,field,locale)) WITHOUT ROWID;
CREATE TABLE gcg_card_text(id TEXT PRIMARY KEY,slot_id TEXT NOT NULL REFERENCES gcg_card_slot(id),source_path TEXT NOT NULL,pair_ordinal INTEGER NOT NULL,pointer TEXT NOT NULL,raw_text TEXT NOT NULL,UNIQUE(slot_id,source_path,pair_ordinal)) WITHOUT ROWID;
CREATE TABLE gcg_card_relation(id TEXT PRIMARY KEY,row_id TEXT NOT NULL REFERENCES gcg_card_row(id),pointer TEXT NOT NULL,raw_value TEXT NOT NULL,target_source_path TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('resolved','missing','ambiguous')),candidate_count INTEGER NOT NULL CHECK(candidate_count>=0),search_complete INTEGER NOT NULL CHECK(search_complete=1),UNIQUE(row_id,pointer)) WITHOUT ROWID;
CREATE TABLE gcg_card_candidate(id TEXT PRIMARY KEY,relation_id TEXT NOT NULL REFERENCES gcg_card_relation(id),target_row_id TEXT NOT NULL REFERENCES gcg_card_row(id),UNIQUE(relation_id,target_row_id)) WITHOUT ROWID;
CREATE TABLE gcg_card_release(manifest_json TEXT NOT NULL);
CREATE INDEX gcg_card_slot_parent ON gcg_card_slot(row_id);
CREATE INDEX gcg_card_text_slot ON gcg_card_text(slot_id);
CREATE INDEX gcg_card_relation_parent ON gcg_card_relation(row_id);
CREATE INDEX gcg_card_candidate_relation ON gcg_card_candidate(relation_id);
CREATE TRIGGER gcg_card_row_i BEFORE INSERT ON gcg_card_row WHEN EXISTS(SELECT 1 FROM gcg_card_row WHERE id=NEW.id OR (source_path=NEW.source_path AND ordinal=NEW.ordinal)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER gcg_card_row_update BEFORE UPDATE ON gcg_card_row BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER gcg_card_row_delete BEFORE DELETE ON gcg_card_row BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER gcg_card_slot_i BEFORE INSERT ON gcg_card_slot WHEN EXISTS(SELECT 1 FROM gcg_card_slot WHERE id=NEW.id OR (row_id=NEW.row_id AND field=NEW.field AND locale=NEW.locale)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER gcg_card_slot_update BEFORE UPDATE ON gcg_card_slot BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER gcg_card_slot_delete BEFORE DELETE ON gcg_card_slot BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER gcg_card_text_i BEFORE INSERT ON gcg_card_text WHEN EXISTS(SELECT 1 FROM gcg_card_text WHERE id=NEW.id OR (slot_id=NEW.slot_id AND source_path=NEW.source_path AND pair_ordinal=NEW.pair_ordinal)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER gcg_card_text_update BEFORE UPDATE ON gcg_card_text BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER gcg_card_text_delete BEFORE DELETE ON gcg_card_text BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER gcg_card_relation_i BEFORE INSERT ON gcg_card_relation WHEN EXISTS(SELECT 1 FROM gcg_card_relation WHERE id=NEW.id OR (row_id=NEW.row_id AND pointer=NEW.pointer)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER gcg_card_relation_update BEFORE UPDATE ON gcg_card_relation BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER gcg_card_relation_delete BEFORE DELETE ON gcg_card_relation BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER gcg_card_candidate_i BEFORE INSERT ON gcg_card_candidate WHEN EXISTS(SELECT 1 FROM gcg_card_candidate WHERE id=NEW.id OR (relation_id=NEW.relation_id AND target_row_id=NEW.target_row_id)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER gcg_card_candidate_update BEFORE UPDATE ON gcg_card_candidate BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER gcg_card_candidate_delete BEFORE DELETE ON gcg_card_candidate BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER gcg_card_release_i BEFORE INSERT ON gcg_card_release WHEN EXISTS(SELECT 1 FROM gcg_card_release) BEGIN SELECT RAISE(ABORT,'immutable release');END;
CREATE TRIGGER gcg_card_release_update BEFORE UPDATE ON gcg_card_release BEGIN SELECT RAISE(ABORT,'immutable release');END;
CREATE TRIGGER gcg_card_release_delete BEFORE DELETE ON gcg_card_release BEGIN SELECT RAISE(ABORT,'immutable release');END;
